<section class="page-intro"><span class="eyebrow">YOUR LITTLE FAVORITES</span><h1>Your bag</h1></section><section class="section"><div class="cart-layout"><?php if(!$cart['items']): ?><div class="empty-state"><h2>A little charm is waiting for you.</h2><p>Your bag is empty. Find something lovely in our collection.</p><a class="button" href="/shop">Explore the collection</a></div><?php else: ?><div class="cart-items"><?php foreach($cart['items'] as $line):$p=$line['product']; ?><article class="cart-item"><a href="/product/<?= e($p['slug']) ?>"><img src="<?= e(image_url(product_images($p)[0]??'/assets/favicon.svg')) ?>" alt="<?= e($p['name']) ?>"></a><div><h2><a href="/product/<?= e($p['slug']) ?>"><?= e($p['name']) ?></a></h2><?php if($line['options']): ?><small><?= e($line['options']) ?></small><?php endif ?><p><?= money(base_product_price($p)) ?></p><?php if(!$line['available']): ?><p class="error-text">Stock changed. <?= (int)$p['stock'] ?> available.</p><?php endif ?><div class="quantity-control"><button data-cart-update="<?= e($line['line_key']) ?>" data-value="<?= $line['quantity']-1 ?>" aria-label="Decrease quantity">−</button><span><?= $line['quantity'] ?></span><button data-cart-update="<?= e($line['line_key']) ?>" data-value="<?= $line['quantity']+1 ?>" aria-label="Increase quantity">+</button></div><button class="text-button" data-cart-update="<?= e($line['line_key']) ?>" data-value="0">Remove</button></div><strong><?php if(!empty($line['offer_saving'])): ?><del><?= money($line['line_total']) ?></del><br><?php endif ?><?= money($line['final_line_total']) ?><?php if(!empty($line['offer_title'])): ?><small><?= e($line['offer_title']) ?></small><?php endif ?></strong></article><?php endforeach ?><a href="/shop" class="text-link">Continue shopping</a></div><aside class="order-summary"><h2>A little overview</h2><?php require ROOT.'/app/views/totals.php'; ?><p class="muted">Delivery and stock are confirmed at checkout.</p><a href="/checkout" class="button full">Continue to checkout</a></aside><?php endif ?></div></section>
